INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_COUNTRY_HELP","Det er ingen informasjon om registreringslandet for kontoen din i vårt kontosystem. Kontakt sjefen din for å tildele landet til motparten din.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_VERIFIED_TEXT","Ubekreftet e-post.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_VERIFIED_HELP","Du har ikke bekreftet e-posten din ennå. For å bekrefte registreringen, klikk på lenken i e-posten som ble sendt til deg etter registreringen. Vennligst sjekk innkommende meldinger og også Spam-mappen. Du kan også be om bekreftelseslenke igjen; vennligst gå til siden:");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_CONFIRMED_DIRECTOR_TEXT","Kontoen er deaktivert av din veileder.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_CONFIRMED_DIRECTOR_HELP","Din konto har blitt deaktivert. For mer informasjon, kontakt din veileder.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_PORTAL_CONFIRMER_TEXT","Kontoen er ikke bekreftet av administratoren.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_PORTAL_CONFIRMER_HELP","Registreringen din er notert, og vår leder er i ferd med å bekrefte den for å gi deg full tilgang til portalen. Vent på denne bekreftelsen. Hvis du ønsker å fremskynde prosessen, kan du kontakte lederen din direkte.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ACTIVE_TEXT","Kontoen er deaktivert.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ACTIVE_HELP","Din konto har blitt deaktivert. For mer informasjon, kontakt din leder.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ENTITY_TEXT","Det er ingen juridisk enhet oppført i vårt regnskapssystem.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ENTITY_HELP","Vi har for øyeblikket ikke informasjon om din juridiske enhet i vårt regnskapssystem. Hvis du er en ny motpart og nylig har signert en kontrakt, vær oppmerksom på at det kan ta opptil en dag før denne informasjonen vises i systemet vårt. Hvis varselet vedvarer utover denne tidsrammen, vennligst kontakt din leder for å løse dette problemet.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_PRICELIST_TEXT","Det er ingen prisliste tildelt i vårt regnskapssystem.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_PRICELIST_HELP","Det er ingen informasjon om dine forhandlerforhold i vårt regnskapssystem. Ta kontakt med administratoren din for å få tildelt en prisliste til kontoen din.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"YOUR_ACCOUNT_HAS_ERRORS","Det er feil i kontoen din.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"SHOW_MORE","Vis mer");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PORTAL_MENU_API","API");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ACTIVE_DEALER_TEXT","Motparten er for øyeblikket deaktivert i vårt regnskapssystem.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ACTIVE_DEALER_HELP","Motpartskontoen din er deaktivert. For mer informasjon, vennligst kontakt din leder.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_SALES_TYPES_TEXT","Det er ingen salgsretning spesifisert i vårt regnskapssystem.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_SALES_TYPES_HELP","Salgsretningen for din konto er ikke spesifisert i vårt regnskapssystem. Ta kontakt med din leder for å tildele en salgsretning til motparten din.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"DEALERS_API_DOC","Forhandlers API-dokumentasjon");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"API_SUPERVISOR_ROLE_REQUIRED","For å generere en API-nøkkel, må du ha en konto med rollen \"Supervisor\". Hvis bedriften din ikke har en slik konto for øyeblikket, vennligst kontakt din leder. Alternativt, hvis du bare trenger å opprette en API-nøkkel for fremtidig bruk og bedriften din allerede har en \"Supervisor\"-konto, vennligst ta kontakt med kontoeieren.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"API_API_KEY_WARNING","Ved å generere og bruke API-nøkkelen bekrefter du at du godtar vilkårene for bruk. Alle forespørsler som gjøres med din API-nøkkel vil bli tilskrevet deg. Vær oppmerksom på at generering av en ny API-nøkkel vil deaktivere alle tidligere opprettede nøkler. Det vil være nødvendig å oppdatere nøkkelen i alle systemer som bruker den.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IS_NOT_ENTITY_FOR_PRICES","Vårt regnskapssystem har ingen juridisk person registrert. For å få tilgang til prislister kreves det en aktiv juridisk enhet. Ta kontakt med din leder for å rette opp dette problemet.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"LINKS_TO_PRICE_BACKWARD","Lenker til prislister med bakoverkompatibilitet");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"ATTENTION_DIRECT_LINKS","\"Merk! Direkte nedlastingslenker inneholder API-nøkkelen din i ukryptert form. Ikke del disse koblingene offentlig eller med andre enn tekniske spesialister som er involvert i katalogintegrering. Deling av nøkkelen din gir tilgang til å behandle transaksjoner og forsendelser på vegne av din juridiske enhet. \"");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"IF_FOR_SOME_REASON_NEW_LINKS","Hvis de nye lenkene for nedlasting av prislister av en eller annen grunn ikke passer, kan du bruke lenkene i tabellen nedenfor. Formatet og innholdet i disse gamle prislistene stemmer helt overens med det du er kjent med. Vær imidlertid oppmerksom på at de gamle prislistene ikke tilbyr muligheten til å velge varer basert på tilgjengelighet, ekskludere merverdiavgift fra varekostnadene, eller ta hensyn til de personlige vilkårene i kontrakten til din juridiske enhet. Hvis du ønsker å bruke disse nye funksjonene, se alternativene nedenfor.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICE_RANGE","Område");
