INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICE_FULL_YML_TEXT","Inkluderer omfattende detaljer om varen, inkludert et tilpasset produktbeskrivelsesformat (vendor.model).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICE_FULL_RETAIL_CSV_TEXT","<p>Inneholder <b>maksimal</b> produktinformasjon som er tilgjengelig i en egendefinert beskrivelsestype (vendor.model). Pristype – <b>anbefalt detaljhandel</b>.</p>");
