INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_AVAIL","Tilgjengelighet: På lager. Tar verdiene <b>true</b> hvis produktet er tilgjengelig i det angitte lageret, ellers <b>false</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_DESC"," Beskrivelse av produktetå tilby.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_PURCHASE_TYPE","Kjøpstype. Kan ta verdier:<br/> <ul> <li><b>'på lager'</b> - varen er på lager i minst ett av de valgte varehusene</li> <li><b>' på vei'</b> - varen er i nærmeste levering til lageret i Moskva</li> <li><b>'på forespørsel'</b> - varene kan bringes til lageret i Moskva på forespørsel. <b>Spesielle betalingsbetingelser</b> - sjekk med lederen.</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_DELIVERY_TIME","Leveringstiden for varer på forespørsel til lageret i Moskva måles i dager og kan variere innenfor visse verdier:<br> <ul> <li><b>antall (dager)</b></li> <li> <b>'ikke tilgjengelig lenger'</b> - leveranser stoppes,</li> <li><b>'sjekk'</b> - sjekk med lederen,</li> <li>tom linje - hvis leveringstiden ikke er definert</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_VENDOR","Produsent eller merke (varemerke).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_COUNTRY","Opprinnelsesland for varen.");
