INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_SUPPLYDATE","Neste leveringsdato for varer til Moskva-lageret");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_SUPPLYQUANTITY","Det tilgjengelige antallet varer for bestilling i den kommende leveringen til Moskva-lageret.");
