INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_TYPEPREFIX","Produkttype eller kategori. Tar verdien <b>udefinert</b> hvis den ikke er angitt.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_MODEL","Modell og viktige parametere (for eksempel modellindeks, modifikasjonsfunksjoner, etc.). Tar verdien <b>udefinert</b> hvis den ikke er angitt.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_SALES_NOTES","Elementet brukes til å vise informasjon om:<br> <ul> <li>behovet for å spesifisere leveringstiden med administratoren;</li> <li>oppsigelse av kjøpet av varen (vi leverer ikke element lenger).</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_DELIVERY_OPTIONS","Leveringstid <b>for varene på forespørsel</b> til lageret i Moskva. Verdien sendes i attributtet <b>dager</b>. Den vises kun hvis leveringen er tilgjengelig for varen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_WEIGHT","Elementet er designet for å spesifisere vekten på varen. <b>Vekten er i kilo, inkludert emballasje</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_DIMENSIONS","Elementet er designet for å spesifisere dimensjonene til varen (lengde, bredde, høyde) i emballasjen. <b>Dimensjonene er i centimeter</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_DELIVERY","Tilgjengelighet for levering. Godtar verdier:<br> <ul> <li><b>false</b> — vi sender ikke varen lenger, eller du må sjekke leveringstiden med administratoren;</li> <li><b >true</b> — varen kan leveres;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_PICKUP","Tilgjengelighet for henting. Godtar verdier:<br> <ul> <li><b>false</b> — vi leverer ikke varen lenger, og den er utsolgt;</li> <li><b>sant</b > — varen er på lager eller levering er mulig på forespørsel, du kan reservere den valgte varen og hente den selv;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"NON_STANDART","Ikke-standard elementer");
