INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"PRICES_D_LOCAL_DELIVERY_DAYS","Forespurt leveringstid for varer til lageret i Moskva. Godtar verdier:<br> <ul> <li><b>antall (dager)</b>;</li> <li><b>'not_carry'</b> — vi leverer ikke varen lenger og den er utsolgt;</li> <li><b>'not_defined'</b> — sjekk leveringstiden med lederen,</li> </ul>");
