INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_BRANDMANAGER_TEXT","Du har tilgang til spørringsdelen for merkevaren din. Spesielt for private merker kan du administrere merkevarens katalog på imex.gkrp.local, bekrefte nedlastingsrettigheter for filer og varsle lederen om brukerportalbekreftelser på nettstedet ditt. Du kan også se priser for alle prislister, inkludert de for EU.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_ZIPMANAGER_TEXT","Du har tilgang til å se transaksjoner og tilhørende informasjon knyttet til reservedelssalg, inkludert alle reklamasjoner, samt tilgang til å se alle prislister.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_QUALITYMANAGER_TEXT","Du har tilgang til alle transaksjoner, krav og klager.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_SENIORZIPMANAGER_TEXT","Du kan se transaksjoner og relatert informasjon vedrørende reservedelssalg, håndtere alle reklamasjoner, få tilgang til alle prislister, administrere ansatte i din avdeling, sende varsler til lead manager angående brukerbekreftelser på portalen (hvis brukeren er din kunde), og registrere transaksjoner på vegne av motparten i reservedelssalgsretningen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_SENIORQUALITYMANAGER_TEXT","Du har tilgang til alle transaksjoner, klager og forespørsler (tillegg) relatert til klager. Du kan også redigere ansatte i avdelingen din.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_SENIORCOMPLAINTMANAGER_TEXT","Du har tilgang til alle transaksjoner, klager og forespørsler (tillegg) relatert til klager. Du kan også redigere ansatte i avdelingen din.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_COMPLAINTMANAGER_TEXT","Du har tilgang til kravene der du ble tildelt som ansvarlig ingeniør.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"GROUP_HEADBRANDMANAGER_TEXT","Du har tilgang til spørringsdelen for merkevaren din. Spesielt for private merker kan du administrere merkevarens katalog på imex.gkrp.local, bekrefte nedlastingsrettigheter for filer og varsle lederen om brukerportalbekreftelser på nettstedet ditt. Du kan også se priser for alle prislister, inkludert de for EU.");
