INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_NAME","Vennligst skriv inn produktnavnet for visning i katalogen. Merk at hvis produktet allerede finnes i katalogen, kan det hende at navnet ikke vises. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_BRAND","Vennligst skriv inn produktmerket. Hvis produktet allerede finnes i katalogen, må merkene til produktene samsvare. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_CATEGORY","Velg produktkategori for visning i katalogen. Hvis produktet allerede finnes i katalogen, må produktkategoriene samsvare. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_CODE_1C","Fylles ut bare hvis et slikt produkt allerede finnes i katalogen. Hvis ikke, må feltet stå tomt.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_PRICE","Skriv inn prisen på produktet uten å spesifisere valutaen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_CURRENCY","Velg valutaen som prisen på produktet er angitt i.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_QUANTITY_IN_PACKAGE","Hvis produktet selges i en pakke eller et sett, vennligst skriv inn mengden av produktet i en pakke. Hvis dette feltet står tomt, vil det automatisk bli vurdert som 1 vare per pakke.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_FBS","Skriv inn mengden av produktet du ønsker å selge ved hjelp av FBS-systemet. La dette feltet stå tomt hvis du ikke ønsker å selge produkter ved hjelp av FBS-systemet.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_DELIVERY_TIME","Angi antall dager det vil ta før varene under bestillingen kommer til ditt lager. Dette vil inkludere leveringstiden fra ditt lager til Equip-lageret ved beregning av levering til kunden. La dette feltet stå tomt hvis du ikke ønsker å selge produkter på bestilling.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_DESCRIPTION","Vennligst skriv inn produktbeskrivelsen. Merk at hvis produktet allerede finnes i katalogen, kan det hende at beskrivelsen ikke vises på produktkortet. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_LENGTH","Angi lengden på produktet uten emballasje i millimeter. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_HEIGHT","Angi høyden på produktet uten emballasje i millimeter. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_WIDTH","Skriv inn bredden på produktet uten emballasje i millimeter. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_GROSSLENGTH","Skriv inn lengden på produktet i pakken i millimeter. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_GROSSWIDTH","Skriv inn bredden på produktet i pakken i millimeter. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_GROSSHEIGHT","Skriv inn høyden på produktet i pakken i millimeter. Hvis du endrer dette feltet, må produktet modereres igjen.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,11,"TOOLTIP_WEIGHT","Angi vekten på produktet uten emballasje i kilo. Hvis du endrer dette feltet, må produktet modereres igjen.");
